<?php
require_once __DIR__ . '/../core/db.php';
require_once __DIR__ . '/../core/functions.php';
require_once __DIR__ . '/../core/security.php';
require_once __DIR__ . '/../core/auth.php';
require_once __DIR__ . '/../core/rbac.php';
require_once __DIR__ . '/../core/api_pairing.php';
start_secure_session(); require_login(); ensure_api_pairing_schema();
$u=current_user();
if(!current_user_is_owner() && !has_menu_access($u,'settings','view')) redirect(base_url('admin/dashboard.php'));
$customCss=function_exists('setting')?setting('custom_css',''):'';
$msg=trim((string)($_GET['msg']??''));
$reopen=preg_replace('/[^a-zA-Z0-9_-]/','',(string)($_GET['reopen']??''));
$incoming=db()->query("SELECT * FROM api_pairing_requests WHERE direction='incoming' AND requester_type='backoffice' AND status IN ('pending','approved','rejected') ORDER BY FIELD(status,'pending','approved','rejected'), id DESC LIMIT 100")->fetchAll(PDO::FETCH_ASSOC);
$conns=db()->query("SELECT * FROM api_connections WHERE connection_type='backoffice' ORDER BY (status='active') DESC,id DESC LIMIT 100")->fetchAll(PDO::FETCH_ASSOC);
$pending=count(array_filter($incoming,fn($r)=>($r['status']??'')==='pending'));
$active=count(array_filter($conns,fn($r)=>($r['status']??'')==='active'));
function pairing_status_badge($s){$s=(string)$s;$c=in_array($s,['approved','active','ok'],true)?'ok':($s==='pending'?'warn':'danger');return '<span class="badge '.$c.'">'.e($s).'</span>';}
?>
