<div class="pairing-row"><div><strong><?php echo e($c['connection_name']); ?></strong><small><?php echo e($c['remote_base_url']); ?></small></div><div><span class="muted">Scope</span><small><?php echo e($c['access_scope']); ?></small></div><div><?php echo pairing_status_badge($c['status']); ?></div><div class="inline-actions"><button type="button" class="btn btn-light" data-detail='<?php echo e(json_encode($c,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)); ?>'>Detail</button><form method="post" action="<?php echo e(base_url('admin/api_pairing_action.php')); ?>" onsubmit="return confirm('Nonaktifkan koneksi Back Office ini?')"><input type="hidden" name="_csrf" value="<?php echo e(csrf_generate_token()); ?>"><input type="hidden" name="act" value="deactivate_connection"><input type="hidden" name="id" value="<?php echo (int)$c['id']; ?>"><button class="btn danger-link">Nonaktifkan</button></form></div></div>
