</div></div>
<div class="pairing-modal" id="requestModal"><div class="pairing-modal-box"><div class="pairing-modal-head"><h3>Request Pairing Masuk</h3><button class="pairing-close" data-close-modal type="button">✕</button></div><div class="pairing-modal-body table-wrap"><table class="table compact-table"><thead><tr><th>Waktu</th><th>Peminta</th><th>URL</th><th>Scope</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($incoming as $r): if(($r['status']??'')!=='pending') continue; ?><tr><td><?php echo e($r['created_at']); ?></td><td><?php echo e($r['requester_name']); ?></td><td><?php echo e($r['requester_base_url']); ?></td><td><?php echo e($r['requested_scope']); ?></td><td><?php echo pairing_status_badge($r['status']); ?></td><td><div class="inline-actions"><form method="post" action="<?php echo e(base_url('admin/api_pairing_action.php')); ?>"><input type="hidden" name="_csrf" value="<?php echo e(csrf_generate_token()); ?>"><input type="hidden" name="act" value="approve"><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><button class="btn">Approve</button></form><form method="post" action="<?php echo e(base_url('admin/api_pairing_action.php')); ?>"><input type="hidden" name="_csrf" value="<?php echo e(csrf_generate_token()); ?>"><input type="hidden" name="act" value="reject"><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><button class="btn danger-link">Reject</button></form><button type="button" class="btn btn-light" data-detail='<?php echo e(json_encode($r,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)); ?>'>Detail</button></div></td></tr><?php endforeach; if(!$pending): ?><tr><td colspan="6" class="empty-pairing">Tidak ada request yang menunggu persetujuan.</td></tr><?php endif; ?></tbody></table></div></div></div>
