<div class="pairing-modal" id="detailModal"><div class="pairing-modal-box"><div class="pairing-modal-head"><h3>Detail Pairing</h3><button class="pairing-close" data-close-modal type="button">✕</button></div><div class="pairing-modal-body"><dl class="detail-grid" id="detailGrid"></dl></div></div></div>
</div></div></div><script defer src="<?php echo e(asset_url('assets/app.js')); ?>"></script><script>
(function(){function open(id){var m=document.getElementById(id);if(m)m.classList.add('open')}function close(m){if(m)m.classList.remove('open')}document.querySelectorAll('[data-open-modal]').forEach(function(b){b.addEventListener('click',function(){open(b.getAttribute('data-open-modal'))})});document.querySelectorAll('[data-close-modal]').forEach(function(b){b.addEventListener('click',function(){close(b.closest('.pairing-modal'))})});document.querySelectorAll('.pairing-modal').forEach(function(m){m.addEventListener('click',function(e){if(e.target===m)close(m)})});document.querySelectorAll('[data-detail]').forEach(function(b){b.addEventListener('click',function(){var d={};try{d=JSON.parse(b.getAttribute('data-detail')||'{}')}catch(e){}var labels={connection_name:'Nama koneksi',requester_name:'Peminta',remote_base_url:'URL remote',requester_base_url:'URL peminta',access_scope:'Scope',requested_scope:'Scope diminta',status:'Status',created_at:'Dibuat',approved_at:'Disetujui',last_test_at:'Test terakhir',last_test_status:'Status test',last_test_message:'Pesan test',last_message:'Pesan'};var html='';Object.keys(labels).forEach(function(k){if(d[k]!==undefined&&d[k]!==null&&String(d[k])!=='')html+='<dt>'+labels[k]+'</dt><dd>'+String(d[k]).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})+'</dd>'});document.getElementById('detailGrid').innerHTML=html||'<dd>Tidak ada detail.</dd>';open('detailModal')})});var reopen=<?php echo json_encode($reopen); ?>;if(reopen)open(reopen);document.addEventListener('keydown',function(e){if(e.key==='Escape')document.querySelectorAll('.pairing-modal.open').forEach(close)})})();
</script></body></html>
